    assert not agent_repo.pattern_approved(gate.conn, "shop-api", "npm install")
    outcomes = {r["outcome"] for r in gate.conn.execute("SELECT outcome FROM agent_decisions WHERE agent = 'cursor'")}
    assert outcomes == {"observed"}


