from sololicense.coding.global_install import solo_home

HEALTH_PATH = "/api/coding/agents"


def pidfile() -> Path:
    return solo_home() / "gate.pid"


def logfile() -> Path:
    return solo_home() / "gate.log"


def default_port() -> int:
    """``SOLO_LICENSE_PORT``, else the port of ``SOLO_LICENSE_URL`` (what the hooks call), else 8000."""
    if os.environ.get("SOLO_LICENSE_PORT", "").strip().isdigit():
        return int(os.environ["SOLO_LICENSE_PORT"])
    return urlparse(os.environ.get("SOLO_LICENSE_URL", "http://127.0.0.1:8000")).port or 8000


def _url(host: str, port: int) -> str:
    return f"http://{'127.0.0.1' if host in ('0.0.0.0', '::', '') else host}:{port}"


def healthy(url: str, timeout: float = 2.0) -> bool:
    try:
        with urllib.request.urlopen(url.rstrip("/") + HEALTH_PATH, timeout=timeout) as resp:
            return resp.status == 200
    except Exception:
        return False


def _alive(pid: int) -> bool:
    if pid <= 0:
        return False
    if os.name == "nt":
        # os.kill(pid, 0) would terminate the process on Windows.
        import ctypes

        kernel32 = ctypes.windll.kernel32
        handle = kernel32.OpenProcess(0x1000, False, pid)   # PROCESS_QUERY_LIMITED_INFORMATION
        if not handle:
            return False
        try:
            code = ctypes.c_ulong()
            return bool(kernel32.GetExitCodeProcess(handle, ctypes.byref(code))) and code.value == 259  # STILL_ACTIVE
        finally:
            kernel32.CloseHandle(handle)
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def read_state() -> dict | None:
    try:
        state = json.loads(pidfile().read_text(encoding="utf-8"))
        return state if isinstance(state, dict) and isinstance(state.get("pid"), int) else None
    except (OSError, ValueError):
        return None


def _detach_kwargs() -> dict:
    if os.name == "nt":
        return {"creationflags": subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP}
    return {"start_new_session": True}


def start(host: str = "127.0.0.1", port: int | None = None, *, wait: float = 30.0,
          popen=subprocess.Popen, health=healthy) -> dict:
    """Start the gate in the background unless it already answers."""
    port = port or default_port()
    url = _url(host, port)
    state = read_state()
    if state and _alive(state["pid"]):
        return {"status": "running", **state}
    if health(url):
        return {"status": "external", "url": url}
    home = solo_home()
    home.mkdir(parents=True, exist_ok=True)
    log = logfile()
    # The child runs from the user dir, so make this very package importable there too.
    package_root = str(Path(__file__).resolve().parent.parent)
    pythonpath = os.pathsep.join(p for p in (package_root, os.environ.get("PYTHONPATH", "")) if p)
    with open(log, "ab") as out:
        out.write(f"\n--- {datetime.now(timezone.utc).isoformat()} solo-license serve on {url}\n".encode())
        out.flush()
        process = popen(
            [sys.executable, "-m", "sololicense.cli", "serve", "--host", host, "--port", str(port)],
            stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT, cwd=str(home), close_fds=True,
            env={**os.environ, "PYTHONUNBUFFERED": "1", "PYTHONPATH": pythonpath}, **_detach_kwargs(),
        )
    state = {"pid": process.pid, "host": host, "port": port, "url": url, "log": str(log),
             "started_at": datetime.now(timezone.utc).isoformat(timespec="seconds")}
    pidfile().write_text(json.dumps(state, indent=2) + "\n", encoding="utf-8")
    deadline = time.monotonic() + wait
    while time.monotonic() < deadline:
        if health(url):
            return {"status": "started", **state}
        if process.poll() is not None:
            pidfile().unlink(missing_ok=True)
            return {"status": "failed", **state}
        time.sleep(0.25)
    return {"status": "starting", **state}


def _kill(pid: int) -> None:
    if os.name == "nt":
        subprocess.run(["taskkill", "/PID", str(pid), "/T", "/F"], capture_output=True, check=False)
        return
    try:
        os.killpg(pid, signal.SIGTERM)       # the gate leads its own session
    except (ProcessLookupError, PermissionError):
        return
    for _ in range(40):
        if not _alive(pid):
            return
        time.sleep(0.25)
    try:
        os.killpg(pid, signal.SIGKILL)
    except (ProcessLookupError, PermissionError):
        pass


def stop() -> dict:
    state = read_state()
    if not state:
        url = _url("127.0.0.1", default_port())
        return {"status": "external" if healthy(url) else "not-running", "url": url}
    pid = state["pid"]
    if not _alive(pid):
        pidfile().unlink(missing_ok=True)
        return {"status": "stale", **state}
    _kill(pid)
    for _ in range(40):
        if not _alive(pid):
            break
        time.sleep(0.25)
    pidfile().unlink(missing_ok=True)
    return {"status": "stopped" if not _alive(pid) else "still-running", **state}


def status() -> dict:
    state = read_state()
    alive = bool(state and _alive(state["pid"]))
    url = (state or {}).get("url") or _url("127.0.0.1", default_port())
    return {**(state or {}), "url": url, "running": alive, "healthy": healthy(url), "log": str(logfile())}

"""``solo-license doctor``: is everything in place for the gate to see your agents?

Each check is pass / warn / fail (or info). Any fail makes ``doctor`` exit 1.
Standard library only: it runs before the server's dependencies are installed.
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sqlite3
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Callable

from sololicense.coding import global_install as gi
from sololicense.coding.agents import AGENTS, AgentSpec
from sololicense.coding.install import DEFAULT_URL, MARK, SHIM_SOURCE

# Agent CLIs worth reporting, by executable name; none is required.
AGENT_CLIS = ("claude", "codex", "cursor-agent", "gemini", "copilot", "grok", "kiro-cli", "opencode")


@dataclass(frozen=True)
class Check:
    level: str      # pass | warn | fail | info
    label: str
    detail: str


def _version(exe: str) -> str:
    try:
        result = subprocess.run([exe, "--version"], capture_output=True, text=True, timeout=15,
                                stdin=subprocess.DEVNULL, check=False)
    except (OSError, subprocess.SubprocessError):
        return ""
    lines = (result.stdout or result.stderr or "").strip().splitlines()
    return lines[0].strip()[:80] if lines else ""


def _read(path: Path) -> str:
    if path.is_dir():
        return "".join(p.read_text(encoding="utf-8", errors="ignore") for p in sorted(path.glob("*")) if p.is_file())
    return path.read_text(encoding="utf-8", errors="ignore") if path.is_file() else ""


def _strings(value) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, dict):
        value = list(value.values())
    return [s for v in value for s in _strings(v)] if isinstance(value, list) else []


def _commands(path: Path) -> str:
    """The text a shell would see: JSON string values decoded, other files as they are."""
    text = _read(path)
    if path.suffix == ".json":
        try:
            return "\n".join(_strings(json.loads(text)))
        except ValueError:
            pass
    return text


def _wired(path: Path) -> bool:
    text = _read(path)
    return MARK in text or "/api/hooks/" in text


_SHIM_PATHS = (r'"([^"]+?hook\.py)"', r"'([^']+?hook\.py)'", r'(?:^|\s)([^\s"\']+hook\.py)(?=\s|$)')


def _inspect(spec: AgentSpec, path: Path, scope: str, url: str) -> tuple[str, str]:
    text = _commands(path)
    again = "solo-license init --global" if scope == "global" else f"solo-license init --agent {spec.key}"
    if spec.transport in ("http", "plugin"):
        pattern = r'\?\? "(https?://[^"]+)"' if spec.transport == "plugin" else r'(https?://[^\s"\'`]+?)/api/hooks/'
        urls = sorted(set(re.findall(pattern, text)))
        if urls != [url]:
            return "fail", f"{path} calls {', '.join(urls) or 'no gate'}, not {url}; run: {again} --url {url}"
        return "pass", f"{path} -> {url}"
    shims = sorted({p for rx in _SHIM_PATHS for p in re.findall(rx, text, flags=re.M)})
    if not shims:
        return "warn", f"{path}: no hook.py command found in it; run: {again}"
    missing = [s for s in shims if not Path(s).is_file()]
    if missing:
        return "fail", f"{path} runs {missing[0]}, which is missing; run: {again}"
    source = SHIM_SOURCE.read_text(encoding="utf-8")
    if any(Path(s).read_text(encoding="utf-8", errors="ignore") != source for s in shims):
        return "warn", f"{shims[0]} is older than this solo-license; run: {again}"
    shim_url = os.environ.get("SOLO_LICENSE_URL", DEFAULT_URL).rstrip("/")
    if shim_url != url:
        return "warn", f"{path}: the shim calls {shim_url} (SOLO_LICENSE_URL), not {url}"
    return "pass", f"{path} -> {shims[0]}"


def hook_checks(repo: Path, url: str) -> list[Check]:
    checks: list[Check] = []
    for key, spec in AGENTS.items():
        places = [("repo", repo / spec.config_path), ("global", gi.global_path(key))]
        wired = [(scope, path) for scope, path in places if _wired(path)]
        for scope, path in wired:
            level, detail = _inspect(spec, path, scope, url)
            if level == "pass" and scope == "global" and len(wired) == 2:
                level, detail = "warn", (f"{path}: also wired in this repo, so every event is gated twice; "
                                         f"remove one: solo-license init --global --remove --agent {key}")
            checks.append(Check(level, f"{spec.label} ({scope})", detail))
    if not checks:
        checks.append(Check("fail", "hooks", "No Solo License hooks in this repo or at user level; "
                                             "run: solo-license init --global"))
    return checks


def _neatlogs_saved() -> bool:
    db = Path(os.environ.get("SOLO_LICENSE_DB") or gi.solo_home() / "solo_license.db")
    if not db.is_file():
        return False
    try:
        conn = sqlite3.connect(db.resolve().as_uri() + "?mode=ro", uri=True)
        try:
            row = conn.execute("SELECT value FROM settings WHERE key = 'neatlogs_api_key'").fetchone()
        finally:
            conn.close()
    except sqlite3.Error:
        return False
    return bool(row and str(row[0]).strip())


def run(repo: Path, url: str, *, get: Callable[[str], dict | None],
        which: Callable[[str], str | None] | None = None,
        version: Callable[[str], str] | None = None) -> list[Check]:
    from sololicense import background

    which, version = which or shutil.which, version or _version
    url = url.rstrip("/")
    checks: list[Check] = []
    state = background.read_state()
    if get(f"{url}/api/coding/agents"):
        how = f" (background pid {state['pid']}, log {state.get('log')})" if state else ""
        checks.append(Check("pass", "gate", f"up at {url}{how}"))
        for seen in (get(f"{url}/api/coding") or {}).get("agents", []):
            checks.append(Check("info", f"seen {seen['agent']}",
                                f"{seen['decisions']} decisions, last {seen['last_seen']}"))
    else:
        checks.append(Check("fail", "gate", f"not reachable at {url}; start it: solo-license serve --background"))

    checks += hook_checks(repo, url)

    for exe in AGENT_CLIS:
        found = which(exe)
        checks.append(Check("pass", exe, f"{version(found) or 'found'} ({found})") if found
                      else Check("info", exe, "not found on PATH"))
    entire = which("entire")
    checks.append(Check("pass", "entire", f"{version(entire) or 'found'} ({entire})") if entire else
                  Check("warn", "entire", "Entire CLI not on PATH (optional): failed turns will not link to "
                                          "the session's checkpoints"))

    if os.environ.get("NEATLOGS_API_KEY", "").strip() or _neatlogs_saved():
        checks.append(Check("pass", "neatlogs", "API key configured"))
    else:
        checks.append(Check("warn", "neatlogs", "no API key (optional): traces stay in the local mirror; "
                                                "add one in the dashboard's settings or set NEATLOGS_API_KEY"))
    return checks


def exit_code(checks: list[Check]) -> int:
    return 1 if any(c.level == "fail" for c in checks) else 0


def render(checks: list[Check]) -> str:
    tags = {"pass": "PASS", "warn": "WARN", "fail": "FAIL", "info": "  - "}
    return "\n".join(f"{tags[c.level]}  {c.label:<30} {c.detail}" for c in checks)

"""``solo-license init --global``: Solo License's hooks for every repository on this machine.

Each agent's *user-level* hook file (``~/.claude/settings.json``,
``~/.codex/hooks.json``, ...) gets the same entries ``init`` writes into a
repository, merged with whatever is already there. Agents whose hooks run a
command share one shim at ``~/.solo-license/hook.py``; the repository is
found at hook time from the payload's working directory. ``--dry-run`` shows
the diff, ``--remove`` takes our entries out again. Standard library only.
"""

from __future__ import annotations

import os
from pathlib import Path

from sololicense.coding import install as repo_install
from sololicense.coding.agents import AGENTS, resolve
from sololicense.coding.install import MARK, Change, apply, diff, plan_agent, shim_changes, validate_url

# Where each agent documents its user-level hooks.
GLOBAL_DOCS = {
    "claude-code": "https://code.claude.com/docs/en/hooks",
    "codex": "https://developers.openai.com/codex/hooks",
    "cursor": "https://cursor.com/docs/hooks",
    "gemini": "https://geminicli.com/docs/hooks/reference/",
    "antigravity": "https://antigravity.google/docs/hooks.md",
    "copilot": "https://docs.github.com/en/copilot/reference/copilot-cli-reference/cli-hooks-reference",
    "grok": "https://docs.x.ai/build/features/hooks",
    "windsurf": "https://docs.windsurf.com/windsurf/cascade/hooks",
    "kiro": "https://kiro.dev/docs/hooks/",
    "cline": "https://github.com/cline/cline/blob/main/.clinerules/hooks/README.md",
    "opencode": "https://opencode.ai/docs/plugins",
}

GLOBAL_NOTES = {
    "codex": "Trust the new user hooks once with /hooks. /prompts:trust shows this repo's levels.",
    "cursor": "Type /trust in Agent chat to see this repo's levels.",
    "kiro": "Global hooks need Kiro IDE 1.0.182+ or Kiro CLI 2.13+.",
    "cline": "Enable Hooks in Cline's settings. Cline hooks do not run on Windows.",
    "grok": "Grok also reads ~/.claude/settings.json; if Claude Code is wired too, turn that compatibility off.",
}


def home() -> Path:
    return Path.home()


def solo_home() -> Path:
    """Where Solo License keeps its own user-level files (shim, database, gate pid and log)."""
    return Path(os.environ.get("SOLO_LICENSE_HOME") or home() / ".solo-license")


def _dir(env: str, default: Path) -> Path:
    value = os.environ.get(env, "").strip()
    return Path(value) if value else default


def _codex_home() -> Path:
    return _dir("CODEX_HOME", home() / ".codex")


def global_path(agent: str) -> Path:
    h = home()
    return {
        "claude-code": _dir("CLAUDE_CONFIG_DIR", h / ".claude") / "settings.json",
        "codex": _codex_home() / "hooks.json",
        "cursor": h / ".cursor" / "hooks.json",
        "gemini": h / ".gemini" / "settings.json",
        "antigravity": h / ".gemini" / "config" / "hooks.json",
        "copilot": _dir("COPILOT_HOME", h / ".copilot") / "hooks" / "solo-license.json",
        "grok": h / ".grok" / "hooks" / "solo-license.json",
        "windsurf": h / ".codeium" / "windsurf" / "hooks.json",
        "kiro": h / ".kiro" / "hooks" / "solo-license.json",
        "cline": h / "Documents" / "Cline" / "Hooks",
        "opencode": h / ".config" / "opencode" / "plugins" / "solo-license.ts",
    }[resolve(agent).key]


def hook_path() -> Path:
    return solo_home() / "hook.py"


def detect() -> list[str]:
    """Agents whose user-level folder exists on this machine."""
    h = home()
    probes = {
        "claude-code": [_dir("CLAUDE_CONFIG_DIR", h / ".claude")],
        "codex": [_codex_home()],
        "cursor": [h / ".cursor"],
        "gemini": [h / ".gemini" / "settings.json"],
        "antigravity": [h / ".gemini" / "config", h / ".gemini" / "antigravity-cli"],
        "copilot": [_dir("COPILOT_HOME", h / ".copilot")],
        "grok": [h / ".grok"],
        "windsurf": [h / ".codeium" / "windsurf"],
        "kiro": [h / ".kiro"],
        "cline": [h / "Documents" / "Cline"],
        "opencode": [h / ".config" / "opencode"],
    }
    return [agent for agent, paths in probes.items() if any(p.exists() for p in paths)]


# --- /trust for agents that take user-level slash commands ------------------------

def _trust_steps(url: str) -> str:
    return f"""Show what the coding agent may do alone in the current repository, according to Solo License.

1. Find the repository name: the last folder of `git rev-parse --show-toplevel` (or of the working directory if that fails).
2. Fetch {url}/api/coding?repo=REPO_NAME with REPO_NAME replaced by that name: `curl -s` on macOS and Linux, `Invoke-RestMethod` in Windows PowerShell. Read-only; nothing else to run.
3. Show a short table from its `licenses`: action class, level (L0 asks every time, L1 auto-allows approved command families, L2 auto-allows the whole class), verified and failed runs, and how many verified runs the next level needs.
4. If the request fails, the gate is not running: tell the user to run `solo-license serve --background`, then `solo-license doctor`.
"""


def _codex_prompt(url: str) -> str:
    # Codex expands $1..$9 and $NAME in prompts, so the text holds no dollar sign.
    return ("---\ndescription: Solo License - what the agent may do alone in this repository\n---\n\n"
            + _trust_steps(url))


def _cursor_skill(url: str) -> str:
    return ("---\nname: trust\ndescription: Solo License - show what the agent may do alone in this repository "
            "and how far each action class is from the next level. Use only when the user types /trust.\n---\n\n"
            + _trust_steps(url))


def _extras(agent: str, url: str, remove: bool) -> list[Change]:
    files = {
        "codex": [(_codex_home() / "prompts" / "trust.md", _codex_prompt(url))],
        "cursor": [(home() / ".cursor" / "skills" / "trust" / "SKILL.md", _cursor_skill(url))],
    }.get(agent, [])
    changes = []
    for path, text in files:
        current = path.read_text(encoding="utf-8", errors="ignore") if path.is_file() else ""
        if path.exists() and MARK not in current:
            continue  # someone else's /trust: leave it alone
        change = Change(path, None if remove else text)
        if change.changed:
            changes.append(change)
    return changes


# --- plan, apply ---------------------------------------------------------------------

def plan(agents: list[str], url: str, remove: bool = False) -> list[Change]:
    """Every file change that wires (or unwires) ``agents`` at user level."""
    url = validate_url(url)
    keys = list(dict.fromkeys(resolve(a).key for a in agents))
    hook = hook_path()
    changes: list[Change] = []
    for key in keys:
        changes += plan_agent(key, global_path(key), url, hook, remove)
        changes += _extras(key, url, remove)
    if remove:
        if set(keys) == set(AGENTS):
            changes += shim_changes(hook, remove=True)
    elif any(AGENTS[k].transport == "command" for k in keys):
        changes = shim_changes(hook) + changes
    return changes


def run(agent: str = "auto", url: str = repo_install.DEFAULT_URL, dry_run: bool = False,
        remove: bool = False) -> int:
    if agent == "all" or (remove and agent == "auto"):
        agents = list(AGENTS)
    elif agent == "auto":
        agents = detect() or ["claude-code"]
    else:
        agents = [resolve(agent).key]
    changes = plan(agents, url, remove=remove)
    if dry_run:
        print(diff(changes) or "Nothing to change.")
        return 0
    verbs = {c.path: c.verb for c in changes}
    apply(changes)
    for path, verb in verbs.items():
        print(f"  {verb:<7} {path}")
    if remove:
        print("Removed Solo License's user-level hooks." if changes else "No user-level Solo License hooks found.")
        return 0
    print("" if changes else "  Already up to date.")
    for key in agents:
        spec = AGENTS[key]
        print(f"  {spec.label:<34} {global_path(key)}")
        if key in GLOBAL_NOTES:
            print(f"  {'':<34} note: {GLOBAL_NOTES[key]}")
    print(f"\nEvery repository on this machine now calls {url}.")
    print("Next: solo-license serve --background, then solo-license doctor.")
    return 0

"""``solo-license``: install, run and check Solo License from one command.

    uvx --from git+https://github.com/JAYATIAHUJA/Solo_license solo-license init --agent auto
    solo-license serve            # the local gate + dashboard on http://127.0.0.1:8000
    solo-license doctor           # is the gate up, which agents are wired here
    solo-license prompt --agent codex   # a ready prompt that makes your agent set itself up
    solo-license hook <agent> <event>   # the command-hook shim (normally called by the agent)

``init``, ``doctor``, ``prompt`` and ``hook`` use only the standard library.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.request
from pathlib import Path

REPO_URL = "https://github.com/JAYATIAHUJA/Solo_license"
INSTALL_ONE_LINER = f"uvx --from git+{REPO_URL} solo-license init --agent auto"
DEFAULT_URL = os.environ.get("SOLO_LICENSE_URL", "http://127.0.0.1:8000")


def agent_prompt(agent: str = "auto") -> str:
    """A prompt a user pastes into their coding agent so it installs Solo License itself."""
    target = "the coding agent you are" if agent == "auto" else agent
    return f"""Set up Solo License in this repository for {target}. Solo License answers your permission prompts from a track record you earn here, and checks each turn for over-editing and failing tests.

1. If `uv` is not installed, install it (macOS/Linux: `curl -LsSf https://astral.sh/uv/install.sh | sh`; Windows: `powershell -c "irm https://astral.sh/uv/install.ps1 | iex"`). Ask me before you run that.
2. Run: `uv tool install git+{REPO_URL}`
3. Run: `solo-license init --agent {agent}` in this repository's root. It only adds hook configuration for you and a `.solo-license/` folder; change nothing else.
4. Tell me to run `solo-license serve` in another terminal (it must keep running), then run `solo-license doctor` and show me its output.
5. Summarise which files were added. Do not commit them unless I ask."""


def _get(url: str, timeout: float = 3.0) -> dict | None:
    try:
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            return json.load(resp)
    except Exception:
        return None


def cmd_init(args: argparse.Namespace) -> int:
    from sololicense.coding import install

    install.main([str(args.repo), "--agent", args.agent, "--url", args.url])
    print("\nNext: run `solo-license serve` and keep it running, then `solo-license doctor`.")
    return 0


def cmd_doctor(args: argparse.Namespace) -> int:
    from sololicense.coding.agents import AGENTS

    repo = Path(args.repo).resolve()
    ok = True
    health = _get(f"{args.url}/api/coding/agents")
    print(f"gate     {'up' if health else 'NOT REACHABLE'} at {args.url}")
    if not health:
        ok = False
        print("         start it with: solo-license serve")
    print(f"repo     {repo}")
    for spec in AGENTS.values():
        path = repo / spec.config_path
        wired = path.exists() and ("solo-license" in _read(path) or "/api/hooks/" in _read(path))
        if wired:
            print(f"  wired  {spec.label:<34} {spec.config_path}")
    shim = repo / ".solo-license" / "hook.py"
    if shim.exists():
        print(f"shim     {shim}")
    if health:
        seen = _get(f"{args.url}/api/coding") or {}
        for a in seen.get("agents", []):
            print(f"seen     {a['agent']}: {a['decisions']} decisions, last {a['last_seen']}")
    return 0 if ok else 1


def _read(path: Path) -> str:
    if path.is_dir():
        return "".join(p.read_text(encoding="utf-8", errors="ignore") for p in path.glob("*") if p.is_file())
    return path.read_text(encoding="utf-8", errors="ignore")


def cmd_policy(args: argparse.Namespace) -> int:
    from sololicense.coding import policy

    path = policy.write_starter(Path(args.repo).resolve())
    print(f"Policy file: {path}\nEdit it, then commit it: privilege changes are reviewed like code.")
    return 0


def cmd_prompt(args: argparse.Namespace) -> int:
    print(agent_prompt(args.agent))
    return 0


def cmd_hook(args: argparse.Namespace) -> int:
    from sololicense.coding import shim

    return shim.main(["hook", args.agent, args.event])


def cmd_serve(args: argparse.Namespace) -> int:
    try:
        import uvicorn  # noqa: F401
    except ImportError:
        print("The server needs its dependencies: uv tool install git+" + REPO_URL)
        return 1
    home = Path(os.environ.get("SOLO_LICENSE_HOME", Path.home() / ".solo-license"))
    home.mkdir(parents=True, exist_ok=True)
    os.environ.setdefault("SOLO_LICENSE_DB", str(home / "solo_license.db"))
    os.environ.setdefault("SOLO_LEDGER_REPO", str(home / "ledger"))
    os.environ.setdefault("SOLO_DEMO_MODE", "1")
    import uvicorn

    print(f"Solo License gate on http://{args.host}:{args.port}  (data in {home})")
    uvicorn.run("sololicense.api.app:app", host=args.host, port=args.port)
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="solo-license", description="Earned autonomy for coding agents.")
    sub = parser.add_subparsers(dest="cmd", required=True)

    p = sub.add_parser("init", help="wire the hooks for a coding agent into this repository")
    p.add_argument("--agent", default="auto", help="claude-code, codex, cursor, gemini, antigravity, copilot, "
                                                   "grok, windsurf, kiro, cline, opencode, auto or all")
    p.add_argument("--repo", default=".")
    p.add_argument("--url", default=DEFAULT_URL)
    p.set_defaults(fn=cmd_init)

    p = sub.add_parser("serve", help="run the local gate and dashboard")
    p.add_argument("--host", default="127.0.0.1")
    p.add_argument("--port", type=int, default=8000)
    p.set_defaults(fn=cmd_serve)

    p = sub.add_parser("doctor", help="check the gate and this repository's hooks")
    p.add_argument("--repo", default=".")
    p.add_argument("--url", default=DEFAULT_URL)
    p.set_defaults(fn=cmd_doctor)

    p = sub.add_parser("policy", help="write a starter .solo-license/policy.toml for this repository")
    p.add_argument("action", choices=["init"])
    p.add_argument("--repo", default=".")
    p.set_defaults(fn=cmd_policy)

    p = sub.add_parser("prompt", help="print a prompt that makes your agent install Solo License")
    p.add_argument("--agent", default="auto")
    p.set_defaults(fn=cmd_prompt)

    p = sub.add_parser("hook", help="command-hook shim (called by the agent)")
    p.add_argument("agent")
    p.add_argument("event")
    p.set_defaults(fn=cmd_hook)

    args = parser.parse_args(argv)
    return args.fn(args)


if __name__ == "__main__":
    sys.exit(main())

